function richToolsPage() {
  const tools = [['Encontrar consulados', 'Organize contatos oficiais e documentos importantes.', 'https://images.unsplash.com/photo-1526778548025-fa2f459cd5c1?auto=format&fit=crop&w=1000&q=82'], ['Checklist de mudança', 'Um roteiro para preparar casa, família e chegada.', 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?auto=format&fit=crop&w=1000&q=82'], ['Custo de vida', 'Compare perguntas, prioridades e despesas da nova rotina.', 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&w=1000&q=82'], ['Encontrar escolas', 'Pontos de partida para educação, idioma e acolhimento.', 'https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=1000&q=82'], ['Conversor de moedas', 'Uma interface demonstrativa para planejar entre países.', 'https://images.unsplash.com/photo-1565514020179-026b92b84bb6?auto=format&fit=crop&w=1000&q=82'], ['Encontrar profissionais', 'Acesse o diretório de serviços e conexões.', 'https://images.unsplash.com/photo-1521791055366-0d553872125f?auto=format&fit=crop&w=1000&q=82']];
  return `${header()}<main><section class="topic-hero" style="--topic-image:url('https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1600&q=82')"><div class="container"><span class="eyebrow">BRAZILIANS.ME · Ferramentas</span><h1>Pequenas ferramentas para decisões grandes.</h1><p>Interfaces demonstrativas para organizar perguntas, documentos e próximos passos.</p></div></section><section class="section"><div class="container tool-grid">${tools.map(([title, text, image]) => `<button class="tool-card" type="button" data-tool="${title}"><span class="tool-image" style="background-image:url('${image}')"></span><span class="demo-tag">EM BREVE · DEMO</span><h3>${title}</h3><p>${text}</p><strong>Abrir ferramenta →</strong></button>`).join('')}</div><p id="tool-message" class="community-message" aria-live="polite"></p></section></main>${footer()}`;
}

function richCountryPage(slug) {
  const country = countries.find(item => item.slug === slug) || countries[0];
  const topics = [['Vida prática', 'Documentação, moradia, transporte e serviços locais.'], ['Família e educação', 'Escola, idioma, crianças e vínculos entre países.'], ['Trabalho e carreira', 'Emprego, negócios e reconhecimento de experiências.'], ['Cultura e comunidade', 'Eventos, sabores, encontros e pertencimento.']];
  return `${header()}<main><section class="topic-hero country-hero" style="--topic-image:url('${countryImages[slug]}')"><div class="container"><span class="eyebrow">${country.flag} BRAZILIANS.ME · ${country.name}</span><h1>Brasileiros vivendo em ${country.name}.</h1><p>${country.description} ${country.people}.</p></div></section><section class="section"><div class="container split"><div><div class="eyebrow">${country.city} é o ponto de partida</div><h2>${country.topic}</h2><p class="lede">Uma visão editorial para quem está chegando, criando raízes ou mantendo vínculos com o Brasil.</p></div><div class="country-intro-image" style="background-image:url('${countryImages[slug]}')"><span>${country.city}</span></div></div></section><section class="section lined"><div class="container"><div class="section-head"><div><div class="eyebrow">Explore ${country.name}</div><h2>Informação para a sua próxima decisão.</h2></div><span class="demo-tag">CONTEÚDO DEMONSTRATIVO</span></div><div class="rich-card-grid">${topics.map(([title, text], index) => `<a class="rich-card" href="/${slug}" style="--card-image:url('${editorialSignals[index % editorialSignals.length].image}')"><div class="rich-card-image"></div><div><span class="rich-card-number">0${index + 1}</span><h3>${title}</h3><p>${text}</p><span class="text-link">Explorar tema →</span></div></a>`).join('')}</div></div></section><section class="section country-cta"><div class="container"><h2>Comece pela cidade. Continue pela comunidade.</h2>${link('/comunidade', 'Encontrar brasileiros', 'button')}</div></section></main>${footer()}`;
}

function servicesPage() {
  return `${header()}<main>${pageHero('BRAZILIANS.ME · Conexões', 'Encontre profissionais que entendem a vida brasileira fora do Brasil.', 'Um diretório demonstrativo para aproximar pessoas, serviços e contextos.')}<section class="section"><div class="container"><div class="service-grid">${services.map(([icon, title, text]) => `<article class="service-card"><span class="area-icon">${icon}</span><h3>${title}</h3><p>${text}</p><span class="demo-tag" style="margin-top:16px">PERFIL DEMONSTRATIVO</span></article>`).join('')}</div></div></section><section class="section lined"><div class="container"><div class="profile"><div class="avatar">K</div><div><span class="demo-tag">PERFIL DEMONSTRATIVO DO PROTÓTIPO</span><h2>Kelly Ilkyo</h2><p>Psicóloga · Atendimento online · Público: brasileiros vivendo no exterior · Foco demonstrativo: mulheres brasileiras vivendo fora do Brasil · Português · Brasil / atendimento remoto</p><p style="font-size:13px">Este perfil é utilizado nesta demonstração para ilustrar como profissionais brasileiros poderão apresentar seus serviços no BRAZILIANS.ME.</p></div></div></div></section></main>${footer()}`;
}

function storiesPage() { return `${header()}<main>${pageHero('BRAZILIANS.ME · Vozes', 'Histórias de quem vive o mundo', 'Relatos demonstrativos sobre mudança, identidade, família e recomeços.') }<section class="section"><div class="container story-grid">${stories.map(([number, title, text]) => `<details class="story" id="historia-${number}"><summary><span class="story-number">${number}</span><span class="demo-tag" style="float:right">ABRIR HISTÓRIA</span><h3>${title}</h3></summary><p>${text} Esta leitura será ampliada com relatos, imagens e informações verificadas na versão pública.</p></details>`).join('')}</div></section></main>${footer()}`; }

function communityPage() { const questions = ['Como vocês mantêm o português das crianças?', 'Alguém conhece uma escola brasileira em Lisboa?', 'Como vocês mantêm contato com os avós?', 'Brasileiros em Dublin: como foi o primeiro inverno?']; return `${header()}<main>${pageHero('BRAZILIANS.ME · Comunidade', 'Uma comunidade de brasileiros espalhados pelo mundo.', 'Uma prévia de como pessoas, perguntas e experiências poderão se encontrar.') }<section class="section"><div class="container country-grid">${['Lisboa','Orlando','Dublin','Tóquio','Madrid'].map((city, i) => `<article class="country-card"><span class="flag">${['🇵🇹','🇺🇸','🇮🇪','🇯🇵','🇪🇸'][i]}</span><h3>Brasileiros em ${city}</h3><span class="demo-tag" style="margin-top:auto">CONTEÚDO DE DEMONSTRAÇÃO</span></article>`).join('')}</div></section><section class="section lined"><div class="container"><div class="section-head"><div><div class="eyebrow">Perguntas da comunidade</div><h2>Começar uma conversa.</h2></div></div><div class="story-grid">${questions.map(question => `<article class="story"><span class="demo-tag">CONTEÚDO DE DEMONSTRAÇÃO</span><h3>${question}</h3></article>`).join('')}</div></div></section></main>${footer()}`; }

function toolsPage() { const tools = [['🗺️','Encontrar consulados'],['💰','Custo de vida'],['📋','Checklist de mudança'],['💱','Conversor de moedas'],['🏫','Encontrar escolas'],['🧑‍⚕️','Encontrar profissionais'],['📍','Encontrar brasileiros']]; return `${header()}<main>${pageHero('BRAZILIANS.ME · Ferramentas', 'Pequenas ferramentas para uma vida grande.', 'Interfaces demonstrativas para organizar decisões, perguntas e próximos passos.') }<section class="section"><div class="container topic-grid">${tools.map(([icon, title]) => `<article class="topic"><span>${icon}</span>${title}<small style="display:block;color:var(--coral);font-size:10px;margin-top:10px">EM BREVE · DEMO</small></article>`).join('')}</div></section></main>${footer()}`; }

function participatePage() { return `${header()}<main>${pageHero('BRAZILIANS.ME · Participação', 'Você faz parte dessa comunidade?', 'Estamos construindo o BRAZILIANS.ME para brasileiros que vivem o mundo todos os dias.') }<section class="section"><div class="container form-shell"><span class="demo-tag">FORMULÁRIO DEMONSTRATIVO</span><h2 style="font-size:42px;margin:20px 0 25px">Compartilhe um pouco da sua experiência.</h2><form class="form-grid" id="participate-form"><div><label for="name">Nome</label><input id="name" required placeholder="Como podemos chamar você?" /></div><div><label for="country">País</label><input id="country" required placeholder="Onde você vive hoje?" /></div><div class="field-wide"><label for="city">Cidade</label><input id="city" placeholder="E a sua cidade?" /></div><div class="field-wide"><label for="difficulty">Qual é a maior dificuldade de viver fora do Brasil para você?</label><textarea id="difficulty"></textarea></div><div class="field-wide"><label for="wish">Que informação você gostaria de encontrar aqui?</label><textarea id="wish"></textarea></div><div class="field-wide"><button class="button" type="submit">Enviar contribuição</button><p id="form-message" style="color:var(--coral);font-size:13px;margin:14px 0 0"></p></div></form></div></section></main>${footer()}`; }

function simpleCountry(slug) { const country = countries.find(item => item.slug === slug) || countries[1]; return `${header()}<main>${pageHero(`${country.flag} País · Conteúdo demonstrativo`, `Brasileiros vivendo em ${country.name}`, `Uma página inicial para descobrir cidades, interesses e conexões de brasileiros vivendo em ${country.name}.`)}<section class="section"><div class="container split"><div><div class="eyebrow">Comece por uma cidade</div><h2>${country.city} é o ponto de partida.</h2><p class="lede">${country.description}</p></div><div class="panel"><span class="demo-tag">CONTEÚDO DE PROTÓTIPO</span><h3 style="font-size:23px;margin:22px 0 10px">Áreas de interesse</h3><p style="color:var(--ink-soft)">${country.people}. Comunidade, família, trabalho, educação, saúde, cultura e serviços.</p></div></div></section></main>${footer()}`; }

function render() {
  const path = window.location.pathname.replace(/\/$/, '') || '/';
  const pages = { '/': home, '/portugal': portugal, '/portugal/lisboa': lisboa, '/familia': () => contentPage('familia'), '/plh': () => contentPage('plh'), '/trabalho': () => contentPage('trabalho'), '/saude': () => contentPage('saude'), '/servicos': servicesPage, '/historias': storiesPage, '/comunidade': communityPage, '/ferramentas': toolsPage, '/participar': participatePage };
  pages['/familia'] = () => richContentPage('familia');
  pages['/plh'] = () => richContentPage('plh');
  pages['/trabalho'] = () => richContentPage('trabalho');
  pages['/saude'] = () => richContentPage('saude');
  pages['/servicos'] = richServicesPage;
  pages['/historias'] = richStoriesPage;
  pages['/comunidade'] = richCommunityPage;
  pages['/ferramentas'] = richToolsPage;
  countries.forEach(country => { pages[`/${country.slug}`] = () => richCountryPage(country.slug); });
  pages['/servicos/kelly-ilkiw'] = fullProfessionalPage;
  pages['/servicos/stephan-garcia'] = stephanProfessionalPage;
  const country = countries.find(item => `/${item.slug}` === path);
  app.innerHTML = pages[path] ? pages[path]() : country ? simpleCountry(country.slug) : `${header()}<main class="container empty-route"><div class="eyebrow">Página não encontrada</div><h1>Vamos voltar ao mapa.</h1>${link('/', 'Explorar o mundo', 'button')}</main>${footer()}`;
  window.scrollTo(0, 0);
  initMap();
  initHero();
  if (window.location.hash) {
    const target = document.querySelector(window.location.hash);
    if (target) { if (target.tagName === 'DETAILS') target.open = true; window.setTimeout(() => target.scrollIntoView({ behavior: 'smooth' }), 0); }
  }
  document.querySelectorAll('.editorial-card').forEach((card, index) => {
    if (!card.querySelector('.editorial-action')) card.insertAdjacentHTML('beforeend', '<span class="editorial-action">Abrir história →</span>');
    card.setAttribute('role', 'link');
    card.setAttribute('tabindex', '0');
    card.setAttribute('aria-label', `Abrir história ${index + 1}`);
    const openStory = () => { history.pushState({}, '', `/historias#historia-${String(index + 1).padStart(2, '0')}`); render(); };
    card.addEventListener('click', openStory);
    card.addEventListener('keydown', event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); openStory(); } });
  });
  const profileHeading = document.querySelector('.profile h2');
  if (profileHeading?.textContent.includes('Kelly')) {
    profileHeading.innerHTML = '<a href="/servicos/kelly-ilkiw">Kelly Ilkiw</a>';
    const avatar = profileHeading.closest('.profile')?.querySelector('.avatar');
    if (avatar) avatar.outerHTML = '<img class="profile-photo" src="https://static.wixstatic.com/media/2c945f_ba4d06f9c7cb4b04a2d8462df15ccae7~mv2.jpg/v1/crop/x_0,y_15,w_1022,h_1174/fill/w_305,h_340,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/WhatsApp%20Image%202026-06-23%20at%2018_56_edite.jpg" alt="Kelly Ilkiw" />';
  }
  document.querySelector('#menu-toggle')?.addEventListener('click', () => document.querySelector('#main-nav')?.classList.toggle('open'));
  document.querySelectorAll('.question-card').forEach(button => button.addEventListener('click', () => { document.querySelector('#community-message').textContent = `A pergunta “${button.dataset.question}” foi adicionada à conversa demonstrativa.`; }));
  document.querySelectorAll('.tool-card').forEach(button => button.addEventListener('click', () => { document.querySelector('#tool-message').textContent = `${button.dataset.tool}: esta ferramenta está sendo preparada para a próxima versão.`; }));
  document.querySelector('#participate-form')?.addEventListener('submit', event => { event.preventDefault(); document.querySelector('#form-message').textContent = 'Obrigado. Esta contribuição é apenas uma simulação do protótipo.'; event.target.reset(); });
}

document.addEventListener('click', event => { const anchor = event.target.closest('a'); if (!anchor || !anchor.href.startsWith(window.location.origin) || anchor.target === '_blank') return; event.preventDefault(); const samePage = anchor.pathname === window.location.pathname && anchor.hash; history.pushState({}, '', anchor.pathname + anchor.hash); render(); if (samePage) document.querySelector(anchor.hash)?.scrollIntoView({ behavior: 'smooth' }); });
window.addEventListener('popstate', render);
render();